package org.apache.commons.math.distribution;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.MaxIterationsExceededException;
import org.apache.commons.math.special.Erf;
import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.apache.commons.math3.exception.MathRuntimeException;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for NormalDistributionImpl#cumulativeProbability.
 */
public class NormalDistributionImpl_cumulativeProbability_TriageGen2Test {

    private static final double DELTA = 1e-10;

    @Test
    public void testCumulativeProbability_StandardNormal_AtMean() throws Exception {
        // Mean = 0, SD = 1. Cumulative probability at mean should be 0.5
        NormalDistributionImpl distribution = new NormalDistributionImpl(0.0, 1.0);
        double result = distribution.cumulativeProbability(0.0);
        Assert.assertEquals(0.5, result, DELTA);
    }

    @Test
    public void testCumulativeProbability_StandardNormal_OneSigma() throws Exception {
        // Mean = 0, SD = 1. Cumulative probability at 1 sigma is approx 0.841344746
        NormalDistributionImpl distribution = new NormalDistributionImpl(0.0, 1.0);
        double result = distribution.cumulativeProbability(1.0);
        Assert.assertEquals(0.8413447460685429, result, 1e-9);
    }

    @Test
    public void testCumulativeProbability_StandardNormal_NegativeOneSigma() throws Exception {
        // Mean = 0, SD = 1. Cumulative probability at -1 sigma is approx 0.158655253
        NormalDistributionImpl distribution = new NormalDistributionImpl(0.0, 1.0);
        double result = distribution.cumulativeProbability(-1.0);
        Assert.assertEquals(0.158655253931457, result, 1e-9);
    }

    @Test
    public void testCumulativeProbability_LargeX() throws Exception {
        // As x -> infinity, result should approach 1.0
        NormalDistributionImpl distribution = new NormalDistributionImpl(0.0, 1.0);
        double result = distribution.cumulativeProbability(10.0);
        Assert.assertEquals(1.0, result, 1e-12);
    }

    @Test
    public void testCumulativeProbability_SmallX() throws Exception {
        // As x -> -infinity, result should approach 0.0
        NormalDistributionImpl distribution = new NormalDistributionImpl(0.0, 1.0);
        double result = distribution.cumulativeProbability(-10.0);
        Assert.assertEquals(0.0, result, 1e-12);
    }

    @Test
    public void testCumulativeProbability_CustomMeanAndSD() throws Exception {
        // Mean = 10, SD = 2. x = 10 should be 0.5
        NormalDistributionImpl distribution = new NormalDistributionImpl(10.0, 2.0);
        double result = distribution.cumulativeProbability(10.0);
        Assert.assertEquals(0.5, result, DELTA);

        // x = 12 (one SD above mean)
        double result2 = distribution.cumulativeProbability(12.0);
        Assert.assertEquals(0.8413447460685429, result2, 1e-9);
    }

    @Test(expected = MathIllegalArgumentException.class)
    public void testCumulativeProbability_InvalidStandardDeviation_Zero() throws Exception {
        // Standard deviation must be positive. 
        // Depending on implementation, constructor or method might throw.
        // Based on common Apache Commons Math behavior, SD <= 0 throws exception.
        new NormalDistributionImpl(0.0, 0.0).cumulativeProbability(1.0);
    }

    @Test(expected = MathIllegalArgumentException.class)
    public void testCumulativeProbability_InvalidStandardDeviation_Negative() throws Exception {
        new NormalDistributionImpl(0.0, -1.0).cumulativeProbability(1.0);
    }

    @Test
    public void testCumulativeProbability_ExtremeValues() throws Exception {
        NormalDistributionImpl distribution = new NormalDistributionImpl(0.0, 1.0);

        // Test Double.POSITIVE_INFINITY
        Assert.assertEquals(1.0, distribution.cumulativeProbability(Double.POSITIVE_INFINITY), DELTA);

        // Test Double.NEGATIVE_INFINITY
        Assert.assertEquals(0.0, distribution.cumulativeProbability(Double.NEGATIVE_INFINITY), DELTA);
    }
}
